from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

@task(returns=int)
def get_component_id(A, N, start_node):
    visited = {start_node}
    queue = [start_node]
    min_node = start_node

    while queue:
        u = queue.pop(0)

        if u < min_node:
            min_node = u

        for v in range(N):
            if A[u][v] == 1 and v not in visited:
                visited.add(v)
                queue.append(v)

    return min_node

def main(A):
    N = len(A)

    id_futures = []
    for node in range(N):
        fid = get_component_id(A, N, node)
        id_futures.append(fid)

    all_ids = compss_wait_on(id_futures)

    unique_components = set(all_ids)

    return len(unique_components)
